#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-1-y] [n-y..n-1] -> [n-y..n-1] [x..n-1-y] [0..x-1]
    vector<int> np;
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    for (int placed = 0; placed < n; placed++) {
        // Find where (placed+1) is
        int pos = -1;
        for (int i = placed; i < n; i++) {
            if (p[i] == placed + 1) { pos = i; break; }
        }
        if (pos == placed) continue; // already in place

        // Step 1: Move element from pos to position (n-1) if not already there
        if (pos != n - 1) {
            // x = pos+1, y = n-1-pos. But need x+y < n => pos+1+n-1-pos = n, not < n
            // So use x = pos+1, y = n-1-pos-1 = n-pos-2 if possible (need y>0 => pos < n-2, and x+y = pos+1+n-pos-2 = n-1 < n, good)
            // After this op, element at pos goes to end of new array (prefix becomes suffix)
            // Actually element at pos = last of prefix. Prefix [0..pos] goes to end.
            // Element at pos goes to position n-1. But y = n-pos-2, x = pos+1.
            if (pos < n - 2) {
                int x = pos + 1, y = n - pos - 2;
                // x>0: pos>=0 yes. y>0: pos<n-2 yes. x+y=n-1<n yes.
                ops.push_back({x, y});
                apply(p, x, y);
                pos = n - 1; // element is now at end
            } else {
                // pos == n-2, use x=1, y=1 if n>=3 to rotate, then re-find
                // Actually x=pos+1=n-1, y must be >0 and x+y<n => y<1 => impossible
                // Use x=1, y=1 (swap first and last, keep middle)
                if (n >= 3) {
                    ops.push_back({1, 1});
                    apply(p, 1, 1);
                    for (int i = placed; i < n; i++) if (p[i] == placed+1) { pos = i; break; }
                    if (pos != n-1 && pos != placed) {
                        if (pos < n-2) { int x=pos+1, y=n-pos-2; ops.push_back({x,y}); apply(p,x,y); pos=n-1; }
                    }
                }
            }
        }
        if (pos == placed) continue;
        // Step 2: Move element from position n-1 to position 'placed'
        if (pos == n - 1 && placed < n - 1) {
            int x = placed, y = 1;
            if (x > 0 && x + y < n) {
                // suffix [n-1] goes to front (pos 0), prefix [0..placed-1] goes to end
                // element goes to position 0, but we want position 'placed'
                // Actually: after op, element at n-1 goes to position 0. That's not placed unless placed=0.
                // Use x=placed, y=1: [0..placed-1][placed..n-2][n-1] -> [n-1][placed..n-2][0..placed-1]
                // Element goes to pos 0. Not what we want unless placed=0.
            }
            // Better: x = placed+1, y=1 if placed+2<n
            // [0..placed][placed+1..n-2][n-1] -> [n-1][placed+1..n-2][0..placed]
            // Element at n-1 goes to pos 0. Still not placed.
            // We want element at position placed. Use y = n-placed.
            // Wait: y=n-placed, x=? We need the suffix of length y=n-placed: positions [placed..n-1]. That includes our element.
            // [0..x-1][x..placed-1][placed..n-1] -> [placed..n-1][x..placed-1][0..x-1]
            // Element at n-1 ends up at position n-1-placed (last of suffix block). Not placed.
            // Hmm. Let me just use x=placed, y=1: element goes to pos 0. Then next iter handles it.
            if (placed == 0) { /* element at n-1, target pos 0 */ int xx=1,yy=1; if(n>2){ops.push_back({xx,yy}); apply(p,xx,yy);} continue; }
            if (placed + 1 < n) { ops.push_back({placed, 1}); apply(p, placed, 1); }
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [x, y] : ops) printf("%d %d\n", x, y);
}
